const TRANSITION = 15;

const COLORS = {
  pink: "#FF64B8",
  lightPink: "#FEF3FF",
  orange: "#FF8C42",
  mutedPurple: "#9D829F",
  darkPurple: "#694D6B",
  bg: "#12091A",
  green: "#4ADE80",
  red: "#EF4444",
  yellow: "#FACC15",
  blue: "#60A5FA",
};

const Background: React.FC = () => (
  <AbsoluteFill>
    <Img
      src={staticFile("assets/backgrounds/background.png")}
      style={{ width: "100%", height: "100%", objectFit: "cover" }}
    />
  </AbsoluteFill>
);

const BlackScreen: React.FC = () => (
  <AbsoluteFill style={{ backgroundColor: COLORS.bg }} />
);

// ─────────────────────────────────────────
// SCENE 1: Hashtag Chaos (0:00–2:04) ~52 frames
// ─────────────────────────────────────────
const CHAOS_HASHTAGS = [
  { tag: "#travel", x: 18, y: 12, size: 52, color: COLORS.pink, delay: 2 },
  { tag: "#food", x: 72, y: 8, size: 64, color: COLORS.lightPink, delay: 5 },
  { tag: "#love", x: 40, y: 20, size: 80, color: COLORS.pink, delay: 3 },
  { tag: "#instagood", x: 10, y: 38, size: 44, color: COLORS.mutedPurple, delay: 8 },
  { tag: "#fitness", x: 60, y: 30, size: 58, color: COLORS.orange, delay: 4 },
  { tag: "#beauty", x: 82, y: 42, size: 50, color: COLORS.pink, delay: 6 },
  { tag: "#nature", x: 25, y: 55, size: 46, color: COLORS.blue, delay: 7 },
  { tag: "#style", x: 50, y: 48, size: 70, color: COLORS.lightPink, delay: 2 },
  { tag: "#photography", x: 75, y: 58, size: 42, color: COLORS.mutedPurple, delay: 9 },
  { tag: "#motivation", x: 15, y: 68, size: 48, color: COLORS.yellow, delay: 5 },
  { tag: "#art", x: 88, y: 22, size: 72, color: COLORS.pink, delay: 3 },
  { tag: "#fashion", x: 35, y: 75, size: 54, color: COLORS.orange, delay: 10 },
