  { tag: "#summer", x: 90, y: 65, size: 46, color: COLORS.yellow, delay: 9 },
  { tag: "#tech", x: 5, y: 50, size: 52, color: COLORS.blue, delay: 12 },
  { tag: "#design", x: 30, y: 32, size: 48, color: COLORS.pink, delay: 3 },
];

const SceneHashtagChaos: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  return (
