            style={{ width: 160, height: 160, objectFit: "contain" }}
          />
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

// ─────────────────────────────────────────
// SCENE 2: Most Fade Out (2:04–7:10) ~152 frames
// ─────────────────────────────────────────
const SceneMostFadeOut: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const TAGS_WITH_STATUS = [
    { tag: "#travel", x: 20, y: 15, size: 52, used: false, delay: 2 },
    { tag: "#food", x: 70, y: 10, size: 60, used: true, delay: 4 },
    { tag: "#love", x: 42, y: 22, size: 76, used: false, delay: 3 },
    { tag: "#instagood", x: 12, y: 40, size: 44, used: true, delay: 6 },
    { tag: "#fitness", x: 60, y: 32, size: 56, used: false, delay: 5 },
    { tag: "#beauty", x: 80, y: 44, size: 50, used: true, delay: 8 },
    { tag: "#nature", x: 28, y: 58, size: 46, used: false, delay: 7 },
    { tag: "#style", x: 50, y: 50, size: 68, used: false, delay: 2 },
    { tag: "#photography", x: 75, y: 60, size: 42, used: false, delay: 9 },
    { tag: "#motivation", x: 18, y: 70, size: 48, used: false, delay: 5 },
    { tag: "#art", x: 86, y: 24, size: 70, used: false, delay: 3 },
    { tag: "#fashion", x: 38, y: 78, size: 54, used: true, delay: 10 },
    { tag: "#music", x: 62, y: 75, size: 58, used: false, delay: 4 },
    { tag: "#health", x: 48, y: 88, size: 44, used: false, delay: 8 },
    { tag: "#coffee", x: 78, y: 82, size: 56, used: true, delay: 6 },
    { tag: "#workout", x: 55, y: 18, size: 50, used: false, delay: 7 },
    { tag: "#summer", x: 88, y: 66, size: 46, used: false, delay: 9 },
    { tag: "#design", x: 32, y: 35, size: 48, used: false, delay: 3 },
  ];

  const fadeStartFrame = 55;
  const fadeDuration = 35;

  return (
    <AbsoluteFill style={{ fontFamily: "'Inter', sans-serif" }}>
      <Background />
      <AbsoluteFill>
        {TAGS_WITH_STATUS.map((h, i) => {
          const p = spring({ frame, fps, delay: h.delay, config: { damping: 200 } });
          const fadeOut = h.used
            ? 1
            : interpolate(frame, [fadeStartFrame, fadeStartFrame + fadeDuration], [1, 0], {
                extrapolateLeft: "clamp",
                extrapolateRight: "clamp",
              });

          const usedGlow = h.used
            ? interpolate(frame, [fadeStartFrame + fadeDuration, fadeStartFrame + fadeDuration + 20], [0, 1], {
                extrapolateLeft: "clamp",
                extrapolateRight: "clamp",
              })
            : 0;

          return (
            <div
              key={i}
              style={{
                position: "absolute",
                left: `${h.x}%`,
                top: `${h.y}%`,
                fontSize: h.size,
                fontWeight: 800,
                color: h.used ? COLORS.pink : COLORS.mutedPurple,
                opacity: interpolate(p, [0, 1], [0, 0.9]) * fadeOut,
                transform: `translate(-50%, -50%)`,
                whiteSpace: "nowrap",
                textShadow: h.used ? `0 0 ${40 * usedGlow}px ${COLORS.pink}` : "none",
                transition: "color 0.3s",
              }}
            >
              {h.tag}
            </div>
          );
        })}

        {/* Counter showing "only a fraction" */}
        {frame > fadeStartFrame + fadeDuration && (
          <div style={{
            position: "absolute",
            bottom: 200,
            left: "50%",
            transform: "translateX(-50%)",
            opacity: interpolate(frame, [fadeStartFrame + fadeDuration, fadeStartFrame + fadeDuration + 25], [0, 1], {
              extrapolateLeft: "clamp", extrapolateRight: "clamp",
            }),
          }}>
            <div style={{
              backgroundColor: "rgba(255,100,184,0.1)",
              border: `2px solid ${COLORS.pink}`,
              borderRadius: 24,
              padding: "28px 72px",
              textAlign: "center",
            }}>
              <div style={{ fontSize: 52, fontWeight: 800, color: COLORS.pink }}>
                {(() => {
                  const used = TAGS_WITH_STATUS.filter(t => t.used).length;
                  return `${used} / ${TAGS_WITH_STATUS.length}`;
                })()}
              </div>
              <div style={{ fontSize: 32, color: COLORS.lightPink, marginTop: 8 }}>actually used</div>
            </div>
          </div>
        )}
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

